syntax:
PATCH /resource/:id
Content-Type: application/json

{ ...الحقول المراد تعديلها فقط }

example:
PATCH /api/articles/42 HTTP/1.1
Content-Type: application/json

{ "title": "عنوان جديد فقط" }

// الاستجابة
HTTP/1.1 200 OK

{ "id": 42, "title": "عنوان جديد فقط", "body": "لم يتغيّر" }

DELETE /api/articles/42 HTTP/1.1

// الاستجابة الشائعة
HTTP/1.1 204 No Content

